def factorial(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def count_valid_orderings(names):
    from collections import defaultdict

    # Build the prefix tree
    trie = {}
    for name in names:
        node = trie
        for char in name:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['#'] = node.get('#', 0) + 1  # Mark the end of a name and count occurrences

    # Count the number of valid orderings
    def dfs(node):
        count = 0
        for char in node:
            if char != '#':
                count += dfs(node[char])
        count += 1  # Include the current node itself
        return count

    total_count = 1
    for char in trie:
        subtree_count = dfs(trie[char])
        total_count = (total_count * factorial(subtree_count - 1, MOD)) % MOD

    return total_count

